MATCH (s:PlantItem {tag: 'D-35801'}), (t:PlantItem {tag: 'K-35801'})
RETURN s.tag AS source_tag, t.tag AS target_tag,
       EXISTS {
         MATCH p=(s)-[:send_to*1..]->(t)
         WHERE ALL(n IN nodes(p) WHERE n.tag IS NULL OR n.tag <> 'GV-358001')
       } AS can_flow_without_valve

